                    : BuildPlayerPublicDisplayNameForPrompt(memoryHero),
                DailyText = renderedUser,
                RecentText = renderedUser,
                IsAfef = false,
                IsLlmDialogue = true
            },
            new InteractionMemoryRecoveryComponentSeed
            {
