	foreach (string item2 in BuildWeeklyBatchExpectedReportIds(batch))
	{
		if (!dictionary.TryGetValue(item2, out var value2))
		{
			missingReportIds.Add(item2);
		}
		else if (!value2.Parsed)
		{
			missingReportIds.Add(item2);
